    try:
        expanded_geometry = project_tag_geometry(
            build_tag_geometry(expanded_surface_corners),
            matrix,
        )
    except (TypeError, ValueError):
        return observation.projector.corners
    return expanded_geometry.corners


def _expand_point_from_centre(
    point: Point2D,
    centre: Point2D,
    margin_mm: float,
) -> Point2D:
    direction_x = point.x - centre.x
    direction_y = point.y - centre.y
    distance_mm = math.hypot(direction_x, direction_y)
    if distance_mm <= 1e-12:
        return point
    scale = (distance_mm + margin_mm) / distance_mm
    return Point2D(
        centre.x + direction_x * scale,
        centre.y + direction_y * scale,
    )


